type:
∀ {Index State Value : Type} {zeroState : State} {subState : State → State → State} {zeroValue : Value}
  {subValue : Value → Value → Value} {observe : Index → State → Value} {target : State → Value}
  {observe_zero : ∀ (i : Index), observe i zeroState = zeroValue} {target_zero : target zeroState = zeroValue}
  {observe_sub : ∀ (i : Index) (x y : State), observe i (subState x y) = subValue (observe i x) (observe i y)}
  {target_sub : ∀ (x y : State), target (subState x y) = subValue (target x) (target y)}
  {sub_eq_zero_iff : ∀ (a b : Value), subValue a b = zeroValue ↔ a = b} {zeroState_1 : State}
  {subState_1 : State → State → State} {zeroValue_1 : Value} {subValue_1 : Value → Value → Value}
  {observe_1 : Index → State → Value} {target_1 : State → Value}
  {observe_zero_1 : ∀ (i : Index), observe_1 i zeroState_1 = zeroValue_1}
  {target_zero_1 : target_1 zeroState_1 = zeroValue_1}
  {observe_sub_1 :
    ∀ (i : Index) (x y : State), observe_1 i (subState_1 x y) = subValue_1 (observe_1 i x) (observe_1 i y)}
  {target_sub_1 : ∀ (x y : State), target_1 (subState_1 x y) = subValue_1 (target_1 x) (target_1 y)}
  {sub_eq_zero_iff_1 : ∀ (a b : Value), subValue_1 a b = zeroValue_1 ↔ a = b},
  { zeroState := zeroState, subState := subState, zeroValue := zeroValue, subValue := subValue, observe := observe,
        target := target, observe_zero := observe_zero, target_zero := target_zero, observe_sub := observe_sub,
        target_sub := target_sub, sub_eq_zero_iff := sub_eq_zero_iff } =
      { zeroState := zeroState_1, subState := subState_1, zeroValue := zeroValue_1, subValue := subValue_1,
        observe := observe_1, target := target_1, observe_zero := observe_zero_1, target_zero := target_zero_1,
        observe_sub := observe_sub_1, target_sub := target_sub_1, sub_eq_zero_iff := sub_eq_zero_iff_1 } →
    zeroState = zeroState_1 ∧
      subState = subState_1 ∧ zeroValue = zeroValue_1 ∧ subValue = subValue_1 ∧ observe = observe_1 ∧ target = target_1
